// --- Engine Logic ---
let currentView = 'continents';

function initOrbis() {
    renderMap(currentView);
    setupEventListeners();
}

/**
 * Orchestrates the rendering of geographic shapes
 */
function renderMap(view) {
    const regionGroup = document.getElementById('map-regions');
    const labelGroup = document.getElementById('map-labels');
    regionGroup.innerHTML = '';
    labelGroup.innerHTML = '';

    // Expose the current view to CSS so we can hide/show view-scoped UI
    document.getElementById('app').dataset.view = view;

    // Reset any region zoom on every view change so the SVG isn't stuck at a sub-region
    const svg = document.getElementById('world-map');
    if (svg && window.OrbisCountries) OrbisCountries.resetViewBox(svg);
    // Reset the active focus chip to World whenever we re-enter the map
    currentFocus = 'all';
    document.querySelectorAll('.focus-chip').forEach(c => {
        c.classList.toggle('active', c.dataset.region === 'all');
    });

    if (view === 'continents') {
        renderContinents(regionGroup, labelGroup);
    } else if (view === 'countries') {
        renderCountries(regionGroup, labelGroup);
    } else {
        renderOceans(regionGroup, labelGroup);
    }
}

let currentFocus = 'all';

// ----- Tier (difficulty level) selection ---------------------------------
// L1=Famous 20, L2=Top 40, L3=Top 80 (soon), L4=World Tour (soon).
// Persisted to localStorage so the user's choice survives reloads.
const LEVEL_STORAGE_KEY = 'orbis.selectedLevel';
const MAX_AVAILABLE_LEVEL = 3; // bump as we ship new tiers
let selectedLevel = (() => {
    const stored = parseInt(localStorage.getItem(LEVEL_STORAGE_KEY), 10);
    return Number.isFinite(stored) && stored >= 1 && stored <= MAX_AVAILABLE_LEVEL ? stored : 1;
})();

function setSelectedLevel(level) {
    if (level < 1 || level > 4) return;
    selectedLevel = level;
    localStorage.setItem(LEVEL_STORAGE_KEY, String(level));
    document.querySelectorAll('.tier-chip').forEach(c => {
        c.classList.toggle('active', Number(c.dataset.level) === level);
    });
    // Re-render the country layer so highlighting reflects the new tier.
    // We deliberately only re-render the country paths (not the whole map) so the
    // current Region Focus zoom is preserved.
    if (currentView === 'countries') {
        const regionGroup = document.getElementById('map-regions');
        const labelGroup = document.getElementById('map-labels');
        if (regionGroup) regionGroup.innerHTML = '';
        if (labelGroup) labelGroup.innerHTML = '';
        renderCountries(regionGroup, labelGroup);
    }
}

async function setFocusRegion(region) {
    // Click the currently-active region chip to zoom back out to the world
    if (region !== 'all' && region === currentFocus) region = 'all';

    await OrbisCountries.load();
    const svg = document.getElementById('world-map');
    if (!svg) return;
    if (region === 'all') {
        OrbisCountries.animateViewBoxTo(svg, OrbisCountries.WORLD_VIEWBOX);
    } else {
        const target = OrbisCountries.viewBoxOfContinent(region);
        if (!target) return;
        OrbisCountries.animateViewBoxTo(svg, target);
    }
    currentFocus = region;
    document.querySelectorAll('.focus-chip').forEach(c => {
        c.classList.toggle('active', c.dataset.region === region);
    });
}

async function renderCountries(regionGroup, labelGroup) {
    try {
        await OrbisCountries.load();
    } catch (err) {
        console.error('Orbis: failed to load country data', err);
        return;
    }

    OrbisCountries.renderInto(regionGroup, {
        levelFilter: selectedLevel,
        onHover: (iso2, country) => {
            if (anyQuizActive()) return;
            const name = country?.name || iso2;
            updateStatus(name);
        },
        onUnhover: () => {
            if (!anyQuizActive()) updateStatus('PLANET EARTH');
        },
        onClick: (iso2, country) => {
            if (window.OrbisMission && OrbisMission.isActive()) {
                OrbisMission.handleMapClick(iso2, country);
                return;
            }
            if (window.OrbisGeocode && OrbisGeocode.isActive()) {
                OrbisGeocode.handleMapClick(iso2, country);
                return;
            }
            if (country) showCountryDiscovery(country);
        }
    });

    // ISO labels — only for countries inside the active tier
    for (const country of OrbisCountries.allCountries()) {
        if (country.level > selectedLevel) continue;
        const feature = OrbisCountries.getFeature(country.iso_a2);
        if (!feature) continue;
        const [cx, cy] = OrbisCountries.centroidOfFeature(feature);
        if (cx == null) continue;
        const text = document.createElementNS('http://www.w3.org/2000/svg', 'text');
        text.setAttribute('x', cx);
        text.setAttribute('y', -cy);
        text.setAttribute('text-anchor', 'middle');
        text.setAttribute('class', 'country-label');
        text.textContent = country.iso_a2;
        labelGroup.appendChild(text);
    }
}

function anyQuizActive() {
    return (window.OrbisMission && OrbisMission.isActive()) ||
           (window.OrbisGeocode && OrbisGeocode.isActive());
}

function showCountryDiscovery(country) {
    const overlay = document.getElementById('discovery-overlay');
    document.getElementById('modal-category').textContent = 'COUNTRY';
    document.getElementById('modal-title').textContent = country.name;
    document.getElementById('modal-description').textContent = country.fact_card;
    document.getElementById('stat-area').textContent = country.capital || '—';
    document.getElementById('stat-count').textContent = country.languages.join(', ');
    document.querySelector('#modal-stats .stat-item:nth-child(1) .lbl').textContent = 'Capital';
    document.querySelector('#modal-stats .stat-item:nth-child(2) .lbl').textContent = 'Language';
    document.getElementById('modal-image-wrap').textContent = country.flag_emoji || '🌍';
    overlay.classList.add('visible');
}

function renderContinents(regionGroup, labelGroup) {
    mapAssets.continents.forEach(item => {
        const metadata = geoData.continents.find(d => d.id === item.id);
        
        // Continent Vector Path
        const path = document.createElementNS('http://www.w3.org/2000/svg', 'path');
        path.setAttribute('d', item.path);
        path.setAttribute('class', 'region-path continent');
        path.setAttribute('data-id', item.id);

        setupInteraction(path, metadata);
        regionGroup.appendChild(path);

        // Focal Label (Hidden per user request for implicit learning layout)
        // addLabel(labelGroup, item.labelX, item.labelY, metadata.name);
    });
}

function renderOceans(regionGroup, labelGroup) {
    mapAssets.oceans.forEach(item => {
        const metadata = geoData.oceans.find(d => d.id === item.targetId);
        
        // Ocean Focal Point (Sophisticated Bubble/Target)
        const shape = document.createElementNS('http://www.w3.org/2000/svg', 'circle');
        shape.setAttribute('cx', item.x);
        shape.setAttribute('cy', item.y);
        shape.setAttribute('r', item.radius);
        shape.setAttribute('class', 'region-path ocean-node');
        shape.setAttribute('data-id', item.id);

        setupInteraction(shape, metadata);
        regionGroup.appendChild(shape);

        // Focal Label
        // addLabel(labelGroup, item.x, item.y, metadata.name);
    });
}

// --- Quiz Logic ---
let quizActive = false;
let currentQuizContinent = null;
let currentQuizCountry = null;

function startQuizRound() {
    const availableContinents = Object.keys(countryData).filter(k => countryData[k] && countryData[k].length > 0 && k !== 'antarctica');
    currentQuizContinent = availableContinents[Math.floor(Math.random() * availableContinents.length)];
    
    const countriesList = countryData[currentQuizContinent];
    currentQuizCountry = countriesList[Math.floor(Math.random() * countriesList.length)];
    
    document.querySelector('.status-label').textContent = "FIND CONTINENT FOR:";
    document.getElementById('current-region-name').textContent = currentQuizCountry.toUpperCase();
}

function handleQuizClick(element, metadata) {
    if (metadata.id === currentQuizContinent) {
        element.classList.add('correct-flash');
        setTimeout(() => {
            element.classList.remove('correct-flash');
            startQuizRound();
        }, 1000);
    } else {
        element.classList.add('incorrect-flash');
        const regionName = document.getElementById('current-region-name');
        regionName.classList.add('shake');
        
        setTimeout(() => {
            element.classList.remove('incorrect-flash');
            regionName.classList.remove('shake');
        }, 600);
    }
}

function setupInteraction(element, metadata) {
    // Hover: Update the status bar if not in quiz mode
    element.onmouseenter = () => {
        if (!quizActive) updateStatus(metadata.name);
    };
    element.onmouseleave = () => {
        if (!quizActive) updateStatus('PLANET EARTH');
    };
    
    // Selection: Depending on mode, either test memory or discover details
    element.onclick = () => {
        if (quizActive) {
            handleQuizClick(element, metadata);
        } else {
            showDiscovery(metadata);
        }
    };
}

function addLabel(group, x, y, name) {
    const text = document.createElementNS('http://www.w3.org/2000/svg', 'text');
    text.setAttribute('x', x);
    text.setAttribute('y', y);
    text.setAttribute('text-anchor', 'middle');
    text.setAttribute('class', 'map-label');
    text.textContent = name;
    group.appendChild(text);
}

function updateStatus(name) {
    document.getElementById('current-region-name').textContent = name.toUpperCase();
}

/**
 * Handles discovery modal presentation
 */
function showDiscovery(data) {
    const overlay = document.getElementById('discovery-overlay');
    const type = currentView === 'continents' ? 'CONTINENT' : 'OCEAN';

    document.getElementById('modal-category').textContent = type;
    document.getElementById('modal-title').textContent = data.name;
    document.getElementById('modal-description').textContent = data.description;
    document.getElementById('stat-area').textContent = data.area;
    document.getElementById('stat-count').textContent = data.countries;
    document.querySelector('#modal-stats .stat-item:nth-child(1) .lbl').textContent = 'Area';
    document.querySelector('#modal-stats .stat-item:nth-child(2) .lbl').textContent = 'Countries';
    document.getElementById('modal-image-wrap').textContent = data.icon;

    overlay.classList.add('visible');
}

function setupEventListeners() {
    // Mode Switching
    document.getElementById('view-continents-btn').onclick = () => {
        if (quizActive) return; // Disable switching during quiz
        currentView = 'continents';
        renderMap('continents');
    };

    document.getElementById('view-oceans-btn').onclick = () => {
        if (quizActive) return; // Disable switching during quiz
        currentView = 'oceans';
        renderMap('oceans');
    };

    document.getElementById('view-countries-btn').onclick = () => {
        if (quizActive) return;
        currentView = 'countries';
        renderMap('countries');
    };

    // Region focus chips (Countries view only)
    const focusBar = document.getElementById('region-focus');
    if (focusBar) {
        focusBar.addEventListener('click', e => {
            const chip = e.target.closest('.focus-chip');
            if (!chip) return;
            setFocusRegion(chip.dataset.region);
        });
    }

    // Tier picker — clicking an enabled chip changes the active level
    const tierBar = document.getElementById('tier-picker');
    if (tierBar) {
        tierBar.addEventListener('click', e => {
            const chip = e.target.closest('.tier-chip');
            if (!chip || chip.disabled) return;
            const level = Number(chip.dataset.level);
            setSelectedLevel(level);
        });
        // Reflect persisted level on load
        setSelectedLevel(selectedLevel);
    }

    document.getElementById('play-geocode-btn').onclick = async () => {
        if (window.OrbisMission && OrbisMission.isActive()) OrbisMission.stop();
        if (currentView !== 'countries') {
            currentView = 'countries';
            renderMap('countries');
            // Wait a tick so the country paths exist before Geocode starts.
            await new Promise(r => setTimeout(r, 50));
        }
        OrbisGeocode.start(selectedLevel);
        document.querySelector('.status-label').textContent = 'MYSTERY COUNTRY';
        updateStatus('?????');
    };

    // Mission Quiz Button — engine-driven country-locate quiz
    document.getElementById('start-exploration').onclick = async () => {
        // Tear down Geocode if it's running so the modes don't fight each other
        if (window.OrbisGeocode && OrbisGeocode.isActive()) OrbisGeocode.stop();
        if (window.OrbisMission && OrbisMission.isActive()) return; // already running

        if (currentView !== 'countries') {
            currentView = 'countries';
            renderMap('countries');
            // Let the country paths render before Mission attaches click handlers
            await new Promise(r => setTimeout(r, 60));
        }
        OrbisMission.start(selectedLevel);
    };

    // Modal Close
    const closeBtn = document.getElementById('close-modal');
    closeBtn.onclick = () => {
        document.getElementById('discovery-overlay').classList.remove('visible');
    };

    // Roadmap overlay
    const roadmapBtn = document.getElementById('roadmap-btn');
    const roadmapOverlay = document.getElementById('roadmap-overlay');
    const closeRoadmapBtn = document.getElementById('close-roadmap');
    if (roadmapBtn) {
        roadmapBtn.onclick = () => roadmapOverlay.classList.add('visible');
        closeRoadmapBtn.onclick = () => roadmapOverlay.classList.remove('visible');
    }

    // Close on backdrop click — any visible overlay closes when you click the dimmed area
    window.onclick = (e) => {
        const overlayIds = [
            'discovery-overlay',
            'roadmap-overlay',
            'mission-summary-overlay',
            'geocode-result-overlay'
        ];
        for (const id of overlayIds) {
            const el = document.getElementById(id);
            if (el && e.target === el) el.classList.remove('visible');
        }
    };

    // ESC to close any open overlay
    window.addEventListener('keydown', (e) => {
        if (e.key !== 'Escape') return;
        const overlayIds = [
            'discovery-overlay',
            'roadmap-overlay',
            'mission-summary-overlay',
            'geocode-result-overlay'
        ];
        for (const id of overlayIds) {
            document.getElementById(id)?.classList.remove('visible');
        }
    });
}

// Start
document.addEventListener('DOMContentLoaded', initOrbis);
